package com.tyron.code.ai;

import android.app.AlertDialog;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.EditText;
import android.widget.ProgressBar;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import android.widget.ArrayAdapter;
import android.widget.Spinner;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.button.MaterialButton;
import java.io.File;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.codeassist.unofficial.R;

public final class AICenterFragment extends Fragment {
  private final ExecutorService executor=Executors.newSingleThreadExecutor(); private final StringBuilder conversation=new StringBuilder();
  private AIEngineManager engine; private ChangeApplier applier; private File currentProject; private String lastRequest=""; private AIModels.FixResponse pending;
  private TextView status,chatMessages; private ProgressBar progress; private MaterialButton generate,sendChat,applySuggestion,rollback,openPreview; private EditText chatInput; private ScrollView chatScroll;
  @Nullable @Override public View onCreateView(@NonNull LayoutInflater inflater,@Nullable ViewGroup container,@Nullable Bundle state){return inflater.inflate(R.layout.ai_center_fragment,container,false);}
  @Override public void onCreate(@Nullable Bundle state){super.onCreate(state);if(state!=null){String savedConversation=state.getString("ai_conversation","");conversation.append(savedConversation);lastRequest=state.getString("ai_last_request","");String savedProject=state.getString("ai_project");if(savedProject!=null&&!savedProject.isEmpty())currentProject=new File(savedProject);}}
  @Override public void onViewCreated(@NonNull View view,@Nullable Bundle state){
    engine=new AIEngineManager(requireContext()); status=view.findViewById(R.id.statusText);progress=view.findViewById(R.id.progress);generate=view.findViewById(R.id.generateButton);chatMessages=view.findViewById(R.id.chatMessages);chatInput=view.findViewById(R.id.chatInput);sendChat=view.findViewById(R.id.sendChatButton);chatScroll=view.findViewById(R.id.chatScroll);applySuggestion=view.findViewById(R.id.applySuggestionButton);rollback=view.findViewById(R.id.rollbackButton);openPreview=view.findViewById(R.id.openPreviewButton);
    if(conversation.length()>0)chatMessages.setText(conversation.toString());if(currentProject!=null)openPreview.setVisibility(View.VISIBLE);setupProviders(view);((MaterialToolbar)view.findViewById(R.id.aiToolbar)).setNavigationOnClickListener(v->requireActivity().getSupportFragmentManager().popBackStack());view.findViewById(R.id.settingsButton).setOnClickListener(v->view.findViewById(R.id.providerCard).setVisibility(View.VISIBLE));
    generate.setOnClickListener(v->{EditText input=view.findViewById(R.id.promptInput);String prompt=input.getText()==null?"":input.getText().toString().trim();if(prompt.length()<8){input.setError("اكتب وصفاً أوضح للمشروع");return;}generate(prompt);});sendChat.setOnClickListener(v->sendMessage());applySuggestion.setOnClickListener(v->requestPatch());rollback.setOnClickListener(v->rollback());openPreview.setOnClickListener(v->openPreview());
  }
  private void setupProviders(View view){Spinner spinner=view.findViewById(R.id.providerSpinner);Spinner modelSpinner=view.findViewById(R.id.modelSpinner);java.util.List<AIProviderCatalog.Provider> list=engine.providers();String[] labels=new String[list.size()];for(int i=0;i<list.size();i++)labels[i]=list.get(i).label();spinner.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,labels));android.widget.AdapterView.OnItemSelectedListener providerListener=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){AIProviderCatalog.Provider provider=list.get(pos);engine.selectProvider(provider.id);java.util.List<String> models=provider.models();modelSpinner.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,models));String saved=engine.model(provider);int selected=Math.max(0,models.indexOf(saved));modelSpinner.setSelection(selected);((EditText)view.findViewById(R.id.providerEndpoint)).setText(engine.endpoint(provider));((EditText)view.findViewById(R.id.providerModel)).setText(saved.isEmpty()?provider.model:saved);((EditText)view.findViewById(R.id.providerKey)).setText(engine.savedKey(provider.id));}};spinner.setOnItemSelectedListener(providerListener);for(int i=0;i<list.size();i++)if(list.get(i).id.equals(engine.selectedProvider().id))spinner.setSelection(i);modelSpinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(modelSpinner.getSelectedItem()!=null)((EditText)view.findViewById(R.id.providerModel)).setText(modelSpinner.getSelectedItem().toString());}});view.findViewById(R.id.saveProviderButton).setOnClickListener(v->{AIProviderCatalog.Provider p=list.get(spinner.getSelectedItemPosition());String key=((EditText)view.findViewById(R.id.providerKey)).getText().toString().trim();String endpoint=((EditText)view.findViewById(R.id.providerEndpoint)).getText().toString().trim();String model=((EditText)view.findViewById(R.id.providerModel)).getText().toString().trim();if(key.length()<4){status.setText("AUTH: أدخل مفتاح API صالحاً");return;}if(endpoint.length()<8||!endpoint.startsWith("http")){status.setText("ENDPOINT: أدخل رابط خدمة صحيحاً");return;}if(model.isEmpty()){status.setText("MODEL: اختر نموذجاً");return;}engine.saveProvider(p.id,key,endpoint,model);engine.selectProvider(p.id);status.setText("تم حفظ وتفعيل "+p.name+" — النموذج: "+model);});view.findViewById(R.id.testProviderButton).setOnClickListener(v->{AIProviderCatalog.Provider p=list.get(spinner.getSelectedItemPosition());String key=((EditText)view.findViewById(R.id.providerKey)).getText().toString().trim();String endpoint=((EditText)view.findViewById(R.id.providerEndpoint)).getText().toString().trim();String model=((EditText)view.findViewById(R.id.providerModel)).getText().toString().trim();if(key.length()<4){status.setText("AUTH: أدخل مفتاح API قبل الاختبار");return;}engine.saveProvider(p.id,key,endpoint,model);engine.selectProvider(p.id);v.setEnabled(false);status.setText("جاري اختبار "+p.name+" / "+model+"…");executor.execute(()->{try{String result=engine.testConnection();if(isAdded())requireActivity().runOnUiThread(()->{v.setEnabled(true);status.setText("نجح الاتصال: "+result);});}catch(Exception e){if(isAdded())requireActivity().runOnUiThread(()->{v.setEnabled(true);status.setText("فشل الاختبار: "+e.getMessage());});}});});}
  private void sendMessage(){String message=chatInput.getText()==null?"":chatInput.getText().toString().trim();if(message.isEmpty())return;chatInput.setText("");lastRequest=message;appendMessage("أنت",message);sendChat.setEnabled(false);status.setText("AI يفكر في طلبك…");executor.execute(()->{try{String answer=engine.chat(message,projectContext(),conversation.toString());if(isAdded())requireActivity().runOnUiThread(()->{appendMessage("AI",answer);sendChat.setEnabled(true);applySuggestion.setVisibility(currentProject==null?View.GONE:View.VISIBLE);status.setText(currentProject==null?"أنشئ مشروعاً أولاً لتطبيق اقتراحات الملفات.":"يمكنك مراجعة آخر اقتراح ثم تطبيقه بأمان.");});}catch(Exception e){if(isAdded())requireActivity().runOnUiThread(()->{appendMessage("النظام","تعذر الرد: "+e.getMessage());sendChat.setEnabled(true);status.setText("تحقق من إعداد مفتاح API والاتصال.");});}});}
  private void requestPatch(){if(currentProject==null){Toast.makeText(requireContext(),"أنشئ مشروعاً أولاً",Toast.LENGTH_LONG).show();return;}applySuggestion.setEnabled(false);status.setText("جاري تحويل الطلب إلى اقتراح ملفات…");executor.execute(()->{try{pending=engine.proposeChanges(lastRequest,projectContext(),conversation.toString());if(isAdded())requireActivity().runOnUiThread(()->showProposal());}catch(Exception e){if(isAdded())requireActivity().runOnUiThread(()->{applySuggestion.setEnabled(true);status.setText("فشل إعداد الاقتراح: "+e.getMessage());});}});}
  private void showProposal(){StringBuilder files=new StringBuilder();for(AIModels.GeneratedFile f:pending.files)files.append("• ").append(f.action).append(" ").append(f.path).append("\n");new AlertDialog.Builder(requireContext()).setTitle("مراجعة اقتراح AI").setMessage(pending.rootCause+"\n\n"+pending.explanation+"\n\nالملفات:\n"+files).setNegativeButton("إلغاء",(d,w)->applySuggestion.setEnabled(true)).setPositiveButton("إنشاء نقطة حفظ وتطبيق",(d,w)->applyPending()).show();}
  private void applyPending(){executor.execute(()->{try{int count=applier().apply(currentProject,pending);if(isAdded())requireActivity().runOnUiThread(()->{applySuggestion.setEnabled(true);rollback.setVisibility(View.VISIBLE);applySuggestion.setVisibility(View.GONE);appendMessage("النظام","تم تطبيق "+count+" ملف بعد إنشاء Checkpoint. يمكنك التراجع قبل متابعة البناء.");status.setText("تم التطبيق بأمان. أعد البناء للتحقق من النتيجة.");});}catch(Exception e){if(isAdded())requireActivity().runOnUiThread(()->{applySuggestion.setEnabled(true);status.setText("فشل تطبيق التعديل: "+e.getMessage());});}});}
  private void rollback(){executor.execute(()->{try{boolean ok=applier().rollback();if(isAdded())requireActivity().runOnUiThread(()->{rollback.setVisibility(View.GONE);status.setText(ok?"تم التراجع عن آخر تعديل.":"لا توجد نقطة حفظ متاحة.");appendMessage("النظام",ok?"تمت استعادة حالة المشروع قبل آخر تعديل.":"لا توجد نقطة حفظ متاحة للتراجع.");});}catch(Exception e){if(isAdded())requireActivity().runOnUiThread(()->status.setText("فشل التراجع: "+e.getMessage()));}});}
  private ChangeApplier applier(){if(applier==null)applier=new ChangeApplier(new File(requireContext().getFilesDir(),"ai-checkpoints"));return applier;}
  private String projectContext(){return currentProject==null?"لا يوجد مشروع منشأ بعد":"Project: "+currentProject.getName()+" at "+currentProject.getAbsolutePath();}
  private void appendMessage(String author,String message){String line=author+": "+message+"\n\n";conversation.append(line);chatMessages.append(line);chatScroll.post(()->chatScroll.fullScroll(View.FOCUS_DOWN));}
  private void openPreview(){if(currentProject==null){Toast.makeText(requireContext(),"أنشئ مشروعاً أولاً",Toast.LENGTH_LONG).show();return;}requireActivity().getSupportFragmentManager().beginTransaction().replace(R.id.fragment_container,PreviewFragment.newInstance(currentProject),"ai_preview").addToBackStack("ai_center").commit();}
  private void generate(String prompt){appendMessage("أنت","أنشئ تطبيقاً: "+prompt);generate.setEnabled(false);progress.setVisibility(View.VISIBLE);status.setText("جاري تحليل الفكرة وتجهيز خطة الملفات…");executor.execute(()->{try{AIModels.ProjectResponse result=engine.generateProject(prompt);File workspace=new File(requireContext().getExternalFilesDir("Projects"),"AIProjects");currentProject=new ProjectGenerator(workspace).apply(result);if(isAdded())requireActivity().runOnUiThread(()->{progress.setVisibility(View.GONE);generate.setEnabled(true);openPreview.setVisibility(View.VISIBLE);status.setText("تم إنشاء "+currentProject.getName()+". يمكنك الآن طلب تعديل من الدردشة أو فتح المعاينة.");appendMessage("AI","تم إنشاء المشروع "+currentProject.getName()+". اكتب طلب التعديل ثم اختر مراجعة وتطبيق.");Toast.makeText(requireContext(),"تم إنشاء المشروع: "+currentProject.getName(),Toast.LENGTH_LONG).show();});}catch(Exception e){if(isAdded())requireActivity().runOnUiThread(()->{progress.setVisibility(View.GONE);generate.setEnabled(true);appendMessage("النظام","فشل التوليد: "+e.getMessage());status.setText("تعذر إكمال العملية: "+e.getMessage());});}});}
  @Override public void onSaveInstanceState(@NonNull Bundle out){super.onSaveInstanceState(out);out.putString("ai_conversation",conversation.toString());out.putString("ai_last_request",lastRequest);if(currentProject!=null)out.putString("ai_project",currentProject.getAbsolutePath());}
  @Override public void onDestroy(){super.onDestroy();executor.shutdownNow();}
}
